const s=$('When Called by Intake').first().json;
const rows=$('Find Company by Domain').all().map(i=>i.json).filter(c=>c&&(c.companyId||c.id));
const existing=rows.length?rows[0]:null;
const companyId=existing?String(existing.companyId||existing.id):'';
const cp=(existing&&existing.properties)||{};
const cv=(k)=>{const v=cp[k];return v&&typeof v==='object'?String(v.value==null?'':v.value):String(v==null?'':v);};
const enr=s.company_enrichment||{};
const er=s.employee_resolution||enr.employee_resolution||{};
const domain=String(s.company_domain||'').trim().toLowerCase();
const name=String(s.company_name||'').trim()||(domain?domain.split('.')[0]:'');
const props={};
const notes=[];
if(!companyId){if(name)props.name=name;if(domain)props.domain=domain;}
const crmEmp=cv('numberofemployees');
const resolved=er.employees==null?null:Number(er.employees);
if(resolved!=null&&String(er.source||'')!=='hubspot_company'&&!crmEmp){props.numberofemployees=String(resolved);notes.push('numberofemployees='+resolved+' written from '+String(er.source||'enrichment').replace(/_/g,' ')+' at '+Math.round(Number(er.confidence||0)*100)+'% confidence'+(er.needs_verification?' (unverified, confirm at the booth)':''));}
const canCreate=Boolean(!companyId&&(domain||name));
const hasProps=Object.keys(props).length>0;
let method='PATCH';let url='https://api.hubapi.com/crm/v3/objects/companies/'+(companyId||'0');let action='skipped_no_identity';let body={properties:{}};
if(canCreate){method='POST';url='https://api.hubapi.com/crm/v3/objects/companies';body={properties:props};action='create';}
else if(companyId&&hasProps){method='PATCH';url='https://api.hubapi.com/crm/v3/objects/companies/'+companyId;body={properties:props};action='update';}
else if(companyId){action='no_change';}
return[{json:{company_method:method,company_url:url,company_body:JSON.stringify(body),existing_company_id:companyId,company_action:action,company_props:props,company_write_notes:notes}}];

const plan=$('Resolve Company Write').first().json;
let res={};try{res=$('Create or Update Company').first().json||{};}catch(e){res={};}
const err=res&&res.error?String(typeof res.error==='object'?(res.error.message||JSON.stringify(res.error)):res.error):'';
const newId=res&&res.id?String(res.id):'';
const companyId=newId||plan.existing_company_id||'';
const created=Boolean(plan.company_action==='create'&&newId);
const updated=Boolean(plan.company_action==='update'&&!err);
const warnings=[];
if(plan.company_action==='create'&&!newId)warnings.push('Could not create the HubSpot company for '+((plan.company_props||{}).domain||'this domain')+': '+(err||'no id returned')+'. The contact will not be associated to a company.');
if(plan.company_action==='update'&&err)warnings.push('Could not write enriched company fields: '+err);
if(plan.company_action==='skipped_no_identity')warnings.push('No company domain or name on the scan, so no company record was created.');
return[{json:{company_id:companyId,company_created:created,company_updated:updated,company_action:plan.company_action,company_props_written:plan.company_props||{},company_write_notes:plan.company_write_notes||[],company_warnings:warnings}}];
